//! Facade providing ordinary traits and re-exported procedural macros.

pub use checked_macros_derive::{Greet, Hello, MyTrait};

/// A greeting implemented by the companion derive.
pub trait Greet {
    fn greet(&self) -> String;
}

/// A type name generated by the syn/quote example.
pub trait Hello {
    fn hello(&self) -> &'static str;
}

/// The first named field exposed by the spanned-error example.
pub trait MyTrait {
    fn first_field_name() -> &'static str;
}

#[doc(hidden)]
pub mod __private {
    pub fn format_greeting(name: &str) -> String {
        format!("hello, {name}")
    }
}

/// An exported declarative macro whose helper path follows its defining crate.
#[macro_export]
macro_rules! greet {
    ($name:expr) => {
        $crate::__private::format_greeting($name)
    };
}
